<main class="content"><section class="panel"><div class="panel-head"><div><span class="eyebrow"><?=$type==='test'?'EVALUACIÓN':'ANÁLISIS DE RESULTADOS'?></span><h2><?=$type==='test'?'Tests':'Tabuladores'?></h2><p><?=$type==='test'?'Administra evaluaciones, archivos y enlaces por asignatura.':'Organiza los tabuladores por asignatura, grupo y subgrupo.'?></p></div><a class="primary" href="<?=url('/admin/recursos/formulario?type='.$type)?>">+ Nuevo <?=$type==='test'?'test':'tabulador'?></a></div><?php if(!$resources):?><div class="empty">Todavía no existen registros en este módulo.</div><?php else:?><div class="resource-list"><?php foreach($resources as $r):?><article><span class="file-icon"><?=$type==='test'?'✓':'▦'?></span><div><small><?=e($r['subject']??'General')?><?=$r['group_name']?' · '.e($r['group_name']):''?></small><b><?=e($r['name'])?></b><p><?=e($r['description']?:'Sin descripción')?></p></div><div class="action-row"><a class="view" href="<?=url('/admin/recursos/ver?id='.$r['id'])?>">Ver</a><a class="edit" href="<?=url('/admin/recursos/formulario?id='.$r['id'])?>">Editar</a><form method="post" action="<?=url('/admin/recursos/eliminar')?>" onsubmit="return confirm('¿Eliminar este recurso?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="type" value="<?=$type?>"><button class="danger">Eliminar</button></form></div></article><?php endforeach;?></div><?php endif;?></section></main>
